
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_gdme_0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_gdme_0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.650444769430479e+01, 9.418448073103640e+00, 4.592290268333296e+00, 1.373705126156038e+00, -6.818718507295615e-01, -1.877143458124487e+00, -2.424719037632163e+00, -2.494256738514923e+00, -2.263939223337126e+00, -1.974175650608446e+00, -1.758352086311252e+00, -8.439171477861831e-01, -4.481921857524384e-01, -4.976072362547252e-01, -4.555363561904290e-01, -4.444036791017340e-01, -7.472291194108048e-01, -2.309569889001790e+00, -1.138961035838817e+01, -1.040908892484251e+02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


